//! `.tar.gz` archives of a server directory.

use std::fs::{self, File};
use std::io::{self, Read, Write};
use std::path::Path;

use anyhow::{Context, Result};
use flate2::Compression;
use flate2::read::GzDecoder;
use flate2::write::GzEncoder;
use tar::{Archive, Builder, EntryType, Header};

/// Staging directory for a restore, on the same volume so the final move is a rename.
pub const STAGING_DIR: &str = ".cubeharbor-restore";
/// Regenerated by the server, or not part of the data.
pub const DEFAULT_EXCLUDES: &[&str] =
    &["logs", "crash-reports", "cache", "lost+found", STAGING_DIR];

/// Write `data_dir` to `out` as gzip-compressed tar. Symlinks are stored, never followed. A
/// running server still writes logs and plugin data, so files that vanish are skipped, and files
/// that shrink are padded rather than failing the backup.
pub fn create(data_dir: &Path, exclude: &[String], out: impl Write) -> Result<()> {
    let gz = GzEncoder::new(out, Compression::default());
    let mut tar = Builder::new(gz);
    tar.follow_symlinks(false);
    append_dir(&mut tar, data_dir, Path::new(""), exclude)?;
    tar.into_inner()?.finish()?.flush()?;
    Ok(())
}

fn excluded(rel: &Path, exclude: &[String]) -> bool {
    DEFAULT_EXCLUDES.iter().any(|e| rel == Path::new(e))
        || exclude.iter().any(|e| rel == Path::new(e))
}

fn append_dir<W: Write>(
    tar: &mut Builder<W>,
    root: &Path,
    rel: &Path,
    exclude: &[String],
) -> Result<()> {
    let dir = root.join(rel);
    let mut entries: Vec<_> = fs::read_dir(&dir)
        .with_context(|| format!("reading {}", dir.display()))?
        .collect::<io::Result<_>>()?;
    entries.sort_by_key(|e| e.file_name());
    for entry in entries {
        let rel_path = rel.join(entry.file_name());
        if excluded(&rel_path, exclude) {
            continue;
        }
        append_entry(tar, root, &rel_path, exclude)
            .with_context(|| format!("archiving {}", rel_path.display()))?;
    }
    Ok(())
}

fn append_entry<W: Write>(
    tar: &mut Builder<W>,
    root: &Path,
    rel: &Path,
    exclude: &[String],
) -> Result<()> {
    let path = root.join(rel);
    let meta = match fs::symlink_metadata(&path) {
        Ok(m) => m,
        Err(e) if e.kind() == io::ErrorKind::NotFound => return Ok(()),
        Err(e) => return Err(e.into()),
    };
    let mut header = Header::new_gnu();
    header.set_metadata(&meta);
    if meta.is_dir() {
        tar.append_data(&mut header, rel, io::empty())?;
        append_dir(tar, root, rel, exclude)
    } else if meta.is_symlink() {
        let target = fs::read_link(&path)?;
        header.set_size(0);
        tar.append_link(&mut header, rel, target)?;
        Ok(())
    } else if meta.is_file() {
        let file = match File::open(&path) {
            Ok(f) => f,
            Err(e) if e.kind() == io::ErrorKind::NotFound => return Ok(()),
            Err(e) => return Err(e.into()),
        };
        // Exactly the size in the header, whatever happens to the file meanwhile.
        let body = file.take(meta.len()).chain(io::repeat(0)).take(meta.len());
        tar.append_data(&mut header, rel, body)?;
        Ok(())
    } else {
        Ok(()) // Sockets and FIFOs.
    }
}

/// Unpack an archive into `dest`. `unpack_in` refuses entries that would land outside it.
/// The rest of `input` is read to the end, so a checksum over it covers the whole object.
pub fn extract(mut input: impl Read, dest: &Path) -> Result<()> {
    {
        let mut tar = Archive::new(GzDecoder::new(&mut input));
        tar.set_preserve_permissions(true);
        tar.set_preserve_mtime(true);
        for entry in tar.entries()? {
            let mut entry = entry?;
            if matches!(
                entry.header().entry_type(),
                EntryType::Block | EntryType::Char | EntryType::Fifo
            ) {
                continue;
            }
            let path = entry.path()?.into_owned();
            let inside = entry
                .unpack_in(dest)
                .with_context(|| format!("extracting {}", path.display()))?;
            anyhow::ensure!(
                inside,
                "archive entry {} points outside the server directory",
                path.display()
            );
        }
    }
    io::copy(&mut input, &mut io::sink())?;
    Ok(())
}

/// Replace the contents of `data_dir` with those of its staging directory.
pub fn swap_in_staged(data_dir: &Path) -> Result<()> {
    let staging = data_dir.join(STAGING_DIR);
    for entry in fs::read_dir(data_dir)? {
        let entry = entry?;
        let name = entry.file_name();
        if name == STAGING_DIR || name == "lost+found" {
            continue;
        }
        let path = entry.path();
        if entry.file_type()?.is_dir() {
            fs::remove_dir_all(&path)
        } else {
            fs::remove_file(&path)
        }
        .with_context(|| format!("removing {}", path.display()))?;
    }
    for entry in fs::read_dir(&staging)? {
        let entry = entry?;
        let to = data_dir.join(entry.file_name());
        fs::rename(entry.path(), &to)
            .with_context(|| format!("moving {} into place", to.display()))?;
    }
    fs::remove_dir(&staging)?;
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    pub(crate) fn scratch(name: &str) -> std::path::PathBuf {
        let dir =
            std::env::temp_dir().join(format!("cubeharbor-archive-{name}-{}", std::process::id()));
        let _ = fs::remove_dir_all(&dir);
        fs::create_dir_all(&dir).unwrap();
        dir
    }

    fn sample(root: &Path) {
        fs::create_dir_all(root.join("world/region")).unwrap();
        fs::create_dir_all(root.join("logs")).unwrap();
        fs::create_dir_all(root.join("skip")).unwrap();
        fs::write(root.join("world/region/r.0.0.mca"), b"chunks").unwrap();
        fs::write(root.join("logs/latest.log"), b"noise").unwrap();
        fs::write(root.join("skip/x"), b"x").unwrap();
        fs::write(root.join("server.properties"), b"motd=hi").unwrap();
        std::os::unix::fs::symlink("server.properties", root.join("link")).unwrap();
    }

    #[test]
    fn round_trip_honours_excludes_and_keeps_symlinks() {
        let (src, dst) = (scratch("rt-src"), scratch("rt-dst"));
        sample(&src);
        let mut buf = vec![];
        create(&src, &["skip".to_string()], &mut buf).unwrap();
        extract(buf.as_slice(), &dst).unwrap();
        assert_eq!(
            fs::read(dst.join("world/region/r.0.0.mca")).unwrap(),
            b"chunks"
        );
        assert!(!dst.join("logs").exists() && !dst.join("skip").exists());
        assert_eq!(
            fs::read_link(dst.join("link")).unwrap(),
            Path::new("server.properties")
        );
    }

    #[test]
    fn swap_replaces_everything_but_lost_and_found() {
        let data = scratch("swap");
        fs::create_dir_all(data.join("lost+found")).unwrap();
        fs::create_dir_all(data.join("old")).unwrap();
        fs::write(data.join("old/file"), b"old").unwrap();
        fs::create_dir_all(data.join(STAGING_DIR).join("world")).unwrap();
        fs::write(data.join(STAGING_DIR).join("world/level.dat"), b"new").unwrap();
        swap_in_staged(&data).unwrap();
        assert!(
            !data.join("old").exists()
                && data.join("lost+found").exists()
                && !data.join(STAGING_DIR).exists()
        );
        assert_eq!(fs::read(data.join("world/level.dat")).unwrap(), b"new");
    }

    #[test]
    fn entries_outside_the_directory_are_refused() {
        // tar::Builder won't write "..", so patch the name in the raw header block.
        let mut raw = vec![];
        {
            let mut b = Builder::new(GzEncoder::new(&mut raw, Compression::fast()));
            let mut h = Header::new_gnu();
            h.set_size(1);
            h.set_mode(0o644);
            let name = b"../evil";
            h.as_old_mut().name[..name.len()].copy_from_slice(name);
            h.set_cksum();
            b.append(&h, &b"x"[..]).unwrap();
            b.into_inner().unwrap().finish().unwrap();
        }
        let root = scratch("evil");
        let dest = root.join("dest");
        fs::create_dir_all(&dest).unwrap();
        assert!(extract(raw.as_slice(), &dest).is_err());
        assert!(!root.join("evil").exists());
    }

    #[test]
    fn truncated_archive_fails() {
        let (src, dst) = (scratch("cut-src"), scratch("cut-dst"));
        sample(&src);
        let mut buf = vec![];
        create(&src, &[], &mut buf).unwrap();
        buf.truncate(buf.len() / 2);
        assert!(extract(buf.as_slice(), &dst).is_err());
    }
}
